def can_fit(bottles, h):
    b = sorted(bottles, reverse=True)
    total = 0
    for i in range(0, len(b), 2):
        total += b[i]
        if total > h:
            return False
    return total <= h

n, h = map(int, input().split())
a = list(map(int, input().split()))

lo, hi = 1, n
ans = 1
while lo <= hi:
    mid = (lo + hi) // 2
    if can_fit(a[:mid], h):
        ans = mid
        lo = mid + 1
    else:
        hi = mid - 1

print(ans)

